import sailpoint.object.CertificationItem;
import sailpoint.object.Certification;
import java.util.List;

// 'item' is provided by the SailPoint certification engine context
if (item != null) {
    String entitlementName = item.getExceptionEntitlementName();

    // Flag root or admin safes for additional reviewer scrutiny
    if (entitlementName != null && entitlementName.contains("Master-Safe")) {
        item.setAttribute("highRiskPrivilege", "true");
        item.setSummaryStatus("Requires Executive Approval");
    }
}
return;
